constructor(address authority) {
        if (
            authority != address(0)
                && (_isEip7702DelegatedEOA(authority)
                    || !_hasCanonicalAuthorityMarker(authority)
                    || !_hasCanonicalAuthorityContext(authority))
        ) {
            revert TimeParameterInvalidAuthority(authority);
        }
        governanceAuthority = authority;
    }

constructor(address authority, TimeParameterConfig[] memory configs)
        StreamTimeParameterHost(authority)
    {
        uint256 count = configs.length;
        for (uint256 i = 0; i < count;) {
            _registerTimeParameter(configs[i]);
            unchecked {
                ++i;
            }
        }
    }

